const qc = $input.first().json;

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

if (!qc || !qc.id) {
  const html404 = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>QC no encontrado</title><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="font-family:system-ui;padding:40px;text-align:center"><h1>QC no encontrado</h1><p>No existe un qc_check con ese id, o falta el parametro <code>?qc_id=&lt;uuid&gt;</code> en la URL.</p></body></html>`;
  return [{ json: { html: html404 } }];
}

const items = Array.isArray(qc.items) ? qc.items : (typeof qc.items === 'string' ? JSON.parse(qc.items) : []);
const phaseLabel = (qc.phase_key || '').replace(/_/g, ' ');
const statusBadgeColor = { open:'#888', in_progress:'#3b82f6', complete:'#16a34a', blocked:'#c00', cancelled:'#666' }[qc.status] || '#888';

const itemCards = items.map((it, idx) => {
  const itemId = esc(it.id || ('item-' + idx));
  const label = esc(it.label || ('Item ' + (idx + 1)));
  const desc = esc(it.description || '');
  const status = it.status || 'pending';
  const comment = esc(it.comment || '');
  const cls = (s) => status === s ? ' style="background:#3b82f6;color:#fff"' : '';
  const checkedAt = it.checked_at ? `<small style="color:#888">Ultimo check: ${esc(it.checked_at)}</small>` : '';
  return `<div class="item" data-item-id="${itemId}">
    <h3>${label}</h3>
    ${desc ? `<p class="desc">${desc}</p>` : ''}
    <div class="status-buttons">
      <button type="button" class="btn-pass" data-status="pass"${cls('pass')}>OK</button>
      <button type="button" class="btn-fail" data-status="fail"${cls('fail')}>FALLA</button>
      <button type="button" class="btn-skip" data-status="skip"${cls('skip')}>NO_APLICA</button>
    </div>
    <textarea class="comment" placeholder="Comentario (opcional)">${comment}</textarea>
    <div class="item-status" data-current="${status}">Estado actual: <strong>${status}</strong></div>
    ${checkedAt}
    <div class="save-feedback"></div>
  </div>`;
}).join('');

const html = `<!DOCTYPE html><html lang="es"><head>
<meta charset="utf-8"><title>QC ${esc(phaseLabel)} - ${esc(qc.project_name || '')}</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
  *{box-sizing:border-box}
  body{font-family:system-ui,sans-serif;margin:0;padding:0;background:#f7f7f8;color:#222}
  header{background:#fff;border-bottom:1px solid #ddd;padding:14px 18px;position:sticky;top:0;z-index:5}
  header h1{margin:0;font-size:18px}
  header .meta{font-size:13px;color:#666;margin-top:4px}
  .badge{display:inline-block;padding:3px 10px;border-radius:12px;color:#fff;font-size:11px;text-transform:uppercase;background:${statusBadgeColor};margin-left:6px}
  main{max-width:680px;margin:0 auto;padding:18px}
  .item{background:#fff;border:1px solid #ddd;border-radius:8px;padding:16px;margin-bottom:14px}
  .item h3{margin:0 0 6px;font-size:16px}
  .item .desc{margin:0 0 12px;font-size:14px;color:#555}
  .status-buttons{display:flex;gap:8px;margin-bottom:10px}
  .status-buttons button{flex:1;padding:14px;border:1px solid #ccc;border-radius:6px;background:#fff;font-size:14px;font-weight:600;cursor:pointer;-webkit-tap-highlight-color:transparent}
  .status-buttons button:active{opacity:0.7}
  .status-buttons .btn-pass{color:#16a34a;border-color:#16a34a}
  .status-buttons .btn-fail{color:#c00;border-color:#c00}
  .status-buttons .btn-skip{color:#666}
  textarea.comment{width:100%;min-height:60px;padding:8px;border:1px solid #ddd;border-radius:6px;font-family:inherit;font-size:14px;resize:vertical}
  .item-status{font-size:12px;color:#666;margin-top:8px}
  .save-feedback{font-size:12px;margin-top:6px;min-height:14px}
  .save-feedback.ok{color:#16a34a}
  .save-feedback.err{color:#c00}
</style>
</head>
<body>
<header>
  <h1>QC ${esc(phaseLabel)}<span class="badge">${esc(qc.status)}</span></h1>
  <div class="meta">${esc(qc.project_name || 'Proyecto sin nombre')} - ${esc(qc.location_city || '?')}</div>
</header>
<main>
  ${itemCards || '<p style="text-align:center;color:#888;padding:40px">Esta checklist no tiene items.</p>'}
  <p style="font-size:11px;color:#888;text-align:center;margin-top:24px">qc_id: ${esc(qc.id)}<br>Cada cambio se guarda automaticamente.</p>
</main>
<script>
const QC_ID = ${JSON.stringify(qc.id)};
const API_KEY = window.__API_KEY__ || prompt('x-api-key (necesaria para guardar):') || '';
window.__API_KEY__ = API_KEY;
document.querySelectorAll('.item').forEach(card => {
  const itemId = card.dataset.itemId;
  const buttons = card.querySelectorAll('.status-buttons button');
  const textarea = card.querySelector('.comment');
  const feedback = card.querySelector('.save-feedback');
  const statusEl = card.querySelector('.item-status');
  let pendingTimer = null;
  function save(newStatus) {
    feedback.textContent = 'Guardando...';
    feedback.className = 'save-feedback';
    fetch('/webhook/qc-complete', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': API_KEY },
      body: JSON.stringify({ qc_id: QC_ID, item_id: itemId, status: newStatus, comment: textarea.value })
    }).then(r => r.json()).then(d => {
      if (d && (d.success || d.status === 'ok')) {
        feedback.textContent = 'Guardado';
        feedback.className = 'save-feedback ok';
        statusEl.dataset.current = newStatus;
        statusEl.querySelector('strong').textContent = newStatus;
        buttons.forEach(b => { b.style.background = ''; b.style.color = ''; });
        const active = card.querySelector('[data-status="' + newStatus + '"]');
        if (active) { active.style.background = '#3b82f6'; active.style.color = '#fff'; }
      } else {
        feedback.textContent = 'Error: ' + (d.error || 'desconocido');
        feedback.className = 'save-feedback err';
      }
    }).catch(e => { feedback.textContent = 'Error de red'; feedback.className = 'save-feedback err'; });
  }
  buttons.forEach(b => { b.addEventListener('click', () => save(b.dataset.status)); });
  textarea.addEventListener('input', () => {
    if (pendingTimer) clearTimeout(pendingTimer);
    pendingTimer = setTimeout(() => save(statusEl.dataset.current || 'pending'), 800);
  });
});
</script>
</body></html>`;

return [{ json: { html } }];
